// Builds a short "{L1 title} › {L2 title}" breadcrumb for a given L2 Uniformat code, e.g. "Shell › Roofing".
export function getUniformatBreadcrumb(l2Code: string): string {
  for (const l1 of UNIFORMAT_TREE) {
    const l2 = l1.children?.find((c) => c.code === l2Code);
    if (l2) return `${l1.title} › ${l2.title}`;
  }
  return l2Code;
}
